1	/**
2	 * prefer-early-return — guard clauses over else branches and wrapped tails.
3	 *
4	 * Two shapes are reported:
5	 *
6	 * 1. Any `else`. When the consequent terminates (ends in return/throw/
7	 *    continue/break) the else is pure nesting: de-nest it into a sibling
8	 *    statement — autofixed, unless the else block declares a binding that
9	 *    unwrapping could collide with the enclosing scope. When the consequent
10	 *    does NOT terminate, the branches must become two separate ifs
11	 *    (`if (x)` / `if (!x)`); that rewrite is left to a human, because the
12	 *    consequent may have changed the state the negated condition would read.
13	 *
14	 * 2. A terminating `if` (no else) whose body outweighs the statements after
15	 *    it — the whole happy path wrapped in `if (x) {...}` with a dangling
16	 *    fallback tail. Flip it: `if (!x)` guards the tail, the happy path goes
17	 *    flat. Detect-only; moving blocks across comments is where codemods eat
18	 *    code.
19	 */
20	const TERMINATORS = new Set([
21	    "ReturnStatement",
22	    "ThrowStatement",
23	    "ContinueStatement",
24	    "BreakStatement",
25	]);
26	const DECLARATIONS = new Set([
27	    "VariableDeclaration",
28	    "FunctionDeclaration",
29	    "ClassDeclaration",
30	]);
31	/** A wrapped happy path is only worth flipping when it is a real block. */
32	const MIN_WRAPPED = 4;
33	/** True when control cannot flow past this statement into the next sibling. */
34	function terminates(statement) {
35	    if (!statement)
36	        return false;
37	    if (statement.type === "BlockStatement") {
38	        return terminates(statement.body[statement.body.length - 1]);
39	    }
40	    return TERMINATORS.has(statement.type);
41	}
42	/** Like {@link terminates}, but only for leaving the function entirely. */
43	function exits(statement) {
44	    if (!statement)
45	        return false;
46	    if (statement.type === "BlockStatement") {
47	        return exits(statement.body[statement.body.length - 1]);
48	    }
49	    return (statement.type === "ReturnStatement" || statement.type === "ThrowStatement");
50	}
51	function statementCount(statement) {
52	    return statement.type === "BlockStatement" ? statement.body.length : 1;
53	}
54	/** Unwrapping an else block hoists its statements into the enclosing scope; a
55	 *  top-level declaration there could collide, so those keep a human's eyes. */
56	function declaresBindings(alternate) {
57	    if (alternate.type !== "BlockStatement") {
58	        return DECLARATIONS.has(alternate.type);
59	    }
60	    return alternate.body.some((statement) => DECLARATIONS.has(statement.type));
61	}
62	function fixUnnecessaryElse(sourceCode, fixer, node) {
63	    const elseToken = sourceCode.getTokenBefore(node.alternate, (token) => token.type === "Keyword" && token.value === "else");
64	    // `else if (...)` — dropping the keyword leaves a sibling if.
65	    if (node.alternate.type === "IfStatement") {
66	        return fixer.removeRange([elseToken.range[0], node.alternate.range[0]]);
67	    }
68	    // `else { ... }` — replace keyword-through-block with the block's body.
69	    if (node.alternate.type === "BlockStatement") {
70	        const inner = sourceCode.getText(node.alternate).slice(1, -1).trim();
71	        return fixer.replaceTextRange([elseToken.range[0], node.alternate.range[1]], inner);
