    meta: {
        type: "suggestion",
        docs: {
            description: "Limit the number of boolean logical operators in a single condition or assignment",
        },
        schema: [
            {
                type: "object",
                properties: { max: { type: "integer", minimum: 1 } },
                additionalProperties: false,
            },
        ],
        messages: {
            tooManyOperators: "Condition has {{count}} boolean operators (max {{max}}) — extract a named predicate.",
        },
    },
    create(context) {
        const max = context.options[0]?.max ?? 2;
        function check(expression) {
            if (!expression) {
                return;
            }
            const count = countBooleanOps(expression);
            if (count > max) {
                context.report({
                    node: expression,
                    messageId: "tooManyOperators",
                    data: { count, max },
                });
