613	// Each run answers with its own number and then waits at its gate, so a test decides when it ends.
614	const gated = (runs: number) => {
615	  const sent: OutgoingMessage[] = [];
616	  const socket = {
617	    readyState: WebSocket.OPEN as number,
618	    send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
619	  };
620	  const ws = socket as unknown as WebSocket;
621	  const gates = Array.from({length: runs}, () => deferred());
622	  const handed: SessionEntry[][] = [];
623	  const processMessageStream = async function* (session: ChatSession): AsyncGenerator<MessageChunk> {
624	    const run = handed.length;
625	    handed.push(structuredClone(session.entries));
626	    yield text(`answer ${run}`);
627	    await gates[run].until;
628	    yield STOP;
629	  };
630	  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
631	  const handle = createMessageHandler({processMessageStream} as unknown as ChatOrchestrator);
632	
633	  return {
634	    session,
635	    handed,
636	    release: (run: number) => gates[run].release(),
637	    close: () => {
638	      socket.readyState = WebSocket.CLOSED;
639	    },
640	    frames: () => wire(sent),
641	    send: (raw: unknown) => handle(ws, session, raw),
642	  };
643	};
