      const h = harness([text('<thinking>pondering</thinking>answer'), STOP]);

      await h.send();

      expect(h.frames()).toEqual([
        'upsert 0 user "hello"',
        'upsert 1 thinking ""',
        'delta 1 "pondering"',
        'commit 1',
        'upsert 2 assistant ""',
