import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

// A lookup table, not a switch: each frame the protocol gains is one more row, and no dispatch site reopens.
const validators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validate = validators[message.type];
  return validate ? validate(message) : {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

// Static by design: it has no config to consult, so the handler is what refuses an unlisted frame.
function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = message.limit;
  if (isRefusedLimit(limit)) {
    return {valid: false, error: 'limit must be a non-negative integer'};
  }

  const cursor = readCursor(message.before);
  if (!cursor.valid) return cursor;

  const frame: ListSessionsMessage = {type: 'list_sessions'};
  if (limit !== undefined) frame.limit = limit as number;
  if (cursor.cursor !== undefined) frame.before = cursor.cursor;
  return {valid: true, data: frame};
}

// A limit is a count, so anything but a whole non-negative number is refused rather than repaired into one.
function isRefusedLimit(limit: unknown): boolean {
  return limit !== undefined && (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0);
}

// A cursor is both halves or none: paging on a timestamp alone drops a conversation tied on activity.
type CursorCheck = {valid: true; cursor: SessionCursor | undefined} | {valid: false; error: string};

function readCursor(before: unknown): CursorCheck {
  if (before === undefined) return {valid: true, cursor: undefined};
  if (typeof before !== 'object' || before === null || Array.isArray(before)) {
    return {valid: false, error: 'before must be an object with updatedAt and sessionId'};
  }

  const {updatedAt, sessionId} = before as Record<string, unknown>;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_SESSION_ID_LENGTH) {
    return {valid: false, error: 'before sessionId must be 1 to 128 characters'};
  }

  // Anything a Date.parse or a number cannot read is refused, never treated as no cursor.
  const asTimestamp =
    typeof updatedAt === 'number' ? updatedAt : typeof updatedAt === 'string' ? Date.parse(updatedAt) : Number.NaN;
  if (!Number.isFinite(asTimestamp)) {
    return {valid: false, error: 'before updatedAt must be a parseable date'};
  }
  return {valid: true, cursor: {updatedAt: updatedAt as string | number, sessionId}};
}

