101	/** Tears every socket and server down, so a red test reports instead of hanging the run. */
102	export async function stopEngines(): Promise<void> {
103	  for (const client of clients.splice(0)) client.terminate();
104	  for (const hal of servers.splice(0)) {
105	    const {wss} = hal;
106	    await eventually(() => wss.clients.size === 0);
107	    await hal.stop();
108	  }
109	}
110	
111	/** Waits until `check` holds, polling every 10 ms for at most half a second. */
112	export async function eventually(check: () => boolean): Promise<void> {
113	  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
114	}
115	
116	/** Puts a server a suite built itself on the teardown list, so stopEngines closes it after its sockets drain. */
117	export function registerEngine(hal: HalServer): void {
118	  servers.push(hal);
119	}
120	
121	/** A store with only the five required members, so an optional one can be added, replaced or left out per test. */
122	export function delegatingStore(inner: InMemorySessionStore): SessionStore {
123	  return {
124	    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
125	    get: sessionId => inner.get(sessionId),
126	    delete: sessionId => inner.delete(sessionId),
127	    count: () => inner.count(),
128	    clear: () => inner.clear(),
129	  };
130	}
131	
132	/** The one session a store holds, for asserting what survived a close. */
133	export async function onlySession(store: SessionStore, sessionId: string): Promise<ChatSession | undefined> {
134	  return (await store.get(sessionId)) as ChatSession | undefined;
135	}
